mapper.select:
SELECT m.menu_id AS menuId, m.menu_code AS menuCode, m.menu_nm AS menuNm, m.menu_dc AS menuDc, m.parent_menu_id AS parentMenuId, p.menu_code AS parentMenuCode, m.menu_ordr AS menuOrdr, m.menu_url AS menuUrl, m.icon_nm AS iconNm, m.use_at AS useAt, m.crt_dt AS frstRegistPnttm, m.crt_id AS frstRegisterId, m.upd_dt AS lastUpdtPnttm, m.upd_id AS lastUpdusrId, p.menu_nm AS parentMenuNm, CASE WHEN EXISTS (SELECT 1 FROM tb_menu c WHERE c.parent_menu_id = m.menu_id) THEN 1 ELSE 0 END AS hasChildren FROM tb_menu m LEFT JOIN tb_menu p ON m.parent_menu_id = p.menu_id WHERE 1 = 1
AND m.use_at = #{useAt}
AND m.menu_nm ILIKE '%' || #{searchKeyword} || '%'
AND m.menu_dc ILIKE '%' || #{searchKeyword} || '%'
AND m.menu_url ILIKE '%' || #{searchKeyword} || '%'
ORDER BY m.parent_menu_id, m.menu_ordr, m.menu_id OFFSET #{firstIndex} LIMIT #{recordCountPerPage}
